#!/usr/bin/env python3
"""Generate injector/hook_blob.h from build/hook.bin."""
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "build" / "hook.bin"
dst = root / "injector" / "hook_blob.h"

if not src.exists():
    sys.exit(f"missing {src}; build hook.bin first")

data = src.read_bytes()
lines = [
    "/* Generated by scripts/gen_hook_blob.py. Do not edit. */",
    "#pragma once",
    "static const unsigned char ytps5_hook_blob[] = {",
]
for i in range(0, len(data), 16):
    chunk = data[i:i + 16]
    lines.append("  " + ", ".join(f"0x{b:02x}" for b in chunk) + ",")
lines.append("};")
lines.append(f"static const unsigned int ytps5_hook_blob_len = {len(data)};")
lines.append("")
dst.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {dst} ({len(data)} bytes)")
